sql:
SELECT COUNT(*) AS multi_type_owners FROM (
  SELECT "Task Owner" FROM sheet1 GROUP BY "Task Owner" HAVING COUNT(DISTINCT "Task Type") > 1
)

SELECT "Outcome (Cured/Improved/Deceased)" AS outcome, COUNT(*) AS n
FROM clinical_manifestations
GROUP BY outcome;

SELECT "Contact Management (Yes/No)" AS contact_mgmt, COUNT(*) AS n
FROM clinical_manifestations
GROUP BY contact_mgmt;

SELECT COUNT(*) AS n_distinct FROM (
  SELECT DISTINCT * FROM greenhouse__interview_enhanced
)

SELECT COUNT(*) as cnt FROM (
  SELECT all_conversation_contacts FROM intercom__conversation_enhanced GROUP BY all_conversation_contacts HAVING COUNT(*)>1
)

SELECT COUNT(*) as cnt FROM (
  SELECT all_conversation_contacts FROM intercom__conversation_enhanced GROUP BY all_conversation_contacts HAVING COUNT(*)=1
)

SELECT renewal_window, COUNT(*) AS n FROM (
  SELECT *, regexp_replace(all_company_tags, '.*renewal_window=([^|]+).*', '\1') AS renewal_window FROM intercom__company_enhanced
) GROUP BY renewal_window ORDER BY n DESC
